import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'missing token' });
  // In production, this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/documents/search', extractTenant, async (req, res) => {
  const { q, category, sort_by, order, limit } = req.query;

  let baseQuery = `SELECT id, title, content_preview, category, created_at, owner_id 
                   FROM documents WHERE tenant_id = $1`;
  const params = [req.tenantId];
  let paramIdx = 2;

  if (q) {
    baseQuery += ` AND (title ILIKE $${paramIdx} OR content_preview ILIKE $${paramIdx})`;
    params.push(`%${q}%`);
    paramIdx++;
  }

  if (category) {
    baseQuery += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  // Dynamic sort - vulnerability: sort_by is not validated against allowlist
  const allowedOrders = ['asc', 'desc'];
  const sortOrder = allowedOrders.includes(order?.toLowerCase()) ? order : 'desc';

  if (sort_by) {
    // Developer note: parameterized queries don't work for identifiers
    // TODO: add column validation before next sprint
    baseQuery += ` ORDER BY ${sort_by} ${sortOrder}`;
  } else {
    baseQuery += ` ORDER BY created_at DESC`;
  }

  const resultLimit = Math.min(parseInt(limit) || 20, 100);
  baseQuery += ` LIMIT ${resultLimit}`;

  try {
    const result = await pool.query(baseQuery, params);
    res.json({ documents: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search query failed:', err.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Document detail endpoint
app.get('/api/v2/documents/:id', extractTenant, async (req, res) => {
  const result = await pool.query(
    'SELECT * FROM documents WHERE id = $1 AND tenant_id = $2',
    [req.params.id, req.tenantId]
  );
  if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });
  res.json(result.rows[0]);
});

// Audit log write (append-only)
app.post('/api/v2/audit', extractTenant, async (req, res) => {
  const { action, resource_id, metadata } = req.body;
  const hash = crypto.createHmac('sha256', process.env.AUDIT_HMAC_KEY || 'changeme')
    .update(`${req.tenantId}:${action}:${resource_id}:${Date.now()}`)
    .digest('hex');

  await pool.query(
    'INSERT INTO audit_log (tenant_id, user_id, action, resource_id, metadata, integrity_hash) VALUES ($1,$2,$3,$4,$5,$6)',
    [req.tenantId, req.userId, action, resource_id, JSON.stringify(metadata), hash]
  );
  res.status(201).json({ logged: true });
});

app.listen(3000, () => console.log('Document service listening on :3000'));
